<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait MessageTenantAccessor
{
    private ?MessageTenantVO $_tenant = null;
    public function getTenant(): ?TenantRef
    {
        return $this->_tenant?->value();
    }
    public function tenant(): ?MessageTenantVO
    {
        return $this->_tenant;
    }
    public function isTenantChanged(?self $original = null): bool
    {
        return null !== $this->_tenant && !$this->_tenant->equals($original?->_tenant);
    }
    public function withTenant(MessageTenantVO|TenantRef|null $tenant): self
    {
        $copy = clone $this;
        $copy->_tenant = MessageTenantVO::from($tenant);
        return $copy;
    }
}
